CREATE TABLE `compliance_invitations` ( `id` text PRIMARY KEY NOT NULL, `organisation_id` text NOT NULL, `email` text NOT NULL CHECK ( length(`email`) BETWEEN 3 AND 320 AND `email` = lower(trim(`email`)) ), `display_name` text DEFAULT '' NOT NULL, `role` text NOT NULL CHECK ( `role` IN ('admin', 'case_manager', 'reviewer', 'auditor') ), `status` text DEFAULT 'pending' NOT NULL CHECK ( `status` IN ('pending', 'claimed', 'revoked', 'expired') ), `invited_by_uid` text NOT NULL, `expires_at` text NOT NULL, `claimed_by_uid` text DEFAULT '' NOT NULL, `claimed_at` text DEFAULT '' NOT NULL, `created_at` text NOT NULL, `updated_at` text NOT NULL, CHECK ( (`status` = 'claimed' AND `claimed_by_uid` <> '' AND `claimed_at` <> '') OR (`status` <> 'claimed' AND `claimed_by_uid` = '' AND `claimed_at` = '') ) );
CREATE UNIQUE INDEX `compliance_invitations_org_email_idx` ON `compliance_invitations` (`organisation_id`, `email` COLLATE NOCASE) WHERE `status` IN ('pending', 'claimed');
CREATE INDEX `compliance_invitations_email_status_idx` ON `compliance_invitations` (`email` COLLATE NOCASE, `status`, `expires_at`);
CREATE TABLE `compliance_audit_events` ( `id` text PRIMARY KEY NOT NULL, `organisation_id` text NOT NULL, `actor_type` text NOT NULL CHECK ( `actor_type` IN ('installer', 'compliance', 'platform') ), `actor_uid` text NOT NULL, `event_type` text NOT NULL, `target_type` text NOT NULL, `target_id` text NOT NULL, `summary` text NOT NULL, `metadata` text DEFAULT '{}' NOT NULL CHECK (json_valid(`metadata`)), `created_at` text NOT NULL );
CREATE INDEX `compliance_audit_events_org_time_idx` ON `compliance_audit_events` (`organisation_id`, `created_at`, `id`);
CREATE INDEX `compliance_audit_events_target_idx` ON `compliance_audit_events` (`organisation_id`, `target_type`, `target_id`, `created_at`);
CREATE TABLE `compliance_write_guards` ( `id` text PRIMARY KEY NOT NULL, `organisation_id` text NOT NULL, `operation_id` text NOT NULL, `step_number` integer NOT NULL CHECK (`step_number` > 0), `verified` integer NOT NULL CHECK (`verified` = 1), `created_at` text NOT NULL );
CREATE UNIQUE INDEX `compliance_write_guards_operation_step_idx` ON `compliance_write_guards` (`operation_id`, `step_number`);
CREATE INDEX `compliance_write_guards_org_time_idx` ON `compliance_write_guards` (`organisation_id`, `created_at`, `id`);
CREATE TABLE `trade_mobile_upload_finalisation_guards` ( `id` text PRIMARY KEY NOT NULL, `owner_uid` text NOT NULL CHECK (trim(`owner_uid`) <> ''), `session_id` text NOT NULL CHECK (trim(`session_id`) <> ''), `step_number` integer NOT NULL CHECK (`step_number` > 0), `verified` integer NOT NULL CHECK (`verified` = 1), `created_at` text NOT NULL );
CREATE UNIQUE INDEX `trade_mobile_upload_finalisation_guards_session_step_idx` ON `trade_mobile_upload_finalisation_guards` (`session_id`, `step_number`);
CREATE INDEX `trade_mobile_upload_finalisation_guards_owner_time_idx` ON `trade_mobile_upload_finalisation_guards` (`owner_uid`, `created_at`, `id`);
CREATE TABLE `compliance_evidence_policy_versions` ( `id` text PRIMARY KEY NOT NULL, `organisation_id` text NOT NULL, `activity_version_id` text NOT NULL, `version` integer NOT NULL CHECK (`version` > 0), `title` text NOT NULL, `official_source_url` text NOT NULL, `official_source_title` text NOT NULL, `official_source_version` text NOT NULL, `official_source_sha256` text NOT NULL CHECK ( length(`official_source_sha256`) = 64 AND lower(`official_source_sha256`) NOT GLOB '*[^0-9a-f]*' ), `official_source_checked_at` text NOT NULL, `requirements_complete` integer DEFAULT 0 NOT NULL CHECK ( `requirements_complete` IN (0, 1) ), `publish_state` text DEFAULT 'draft' NOT NULL CHECK ( `publish_state` IN ('draft', 'published', 'withdrawn') ), `published_by_uid` text DEFAULT '' NOT NULL, `published_at` text DEFAULT '' NOT NULL, `withdrawn_by_uid` text DEFAULT '' NOT NULL, `withdrawn_at` text DEFAULT '' NOT NULL, `created_by_uid` text NOT NULL, `created_at` text NOT NULL, `updated_at` text NOT NULL, CHECK ( (`publish_state` = 'draft' AND `published_by_uid` = '' AND `published_at` = '' AND `withdrawn_by_uid` = '' AND `withdrawn_at` = '') OR (`publish_state` = 'published' AND `published_by_uid` <> '' AND `published_at` <> '' AND `withdrawn_by_uid` = '' AND `withdrawn_at` = '') OR (`publish_state` = 'withdrawn' AND `published_by_uid` <> '' AND `published_at` <> '' AND `withdrawn_by_uid` <> '' AND `withdrawn_at` <> '') ) );
CREATE UNIQUE INDEX `compliance_evidence_policies_activity_version_idx` ON `compliance_evidence_policy_versions` (`activity_version_id`, `version`);
CREATE INDEX `compliance_evidence_policies_org_state_idx` ON `compliance_evidence_policy_versions` (`organisation_id`, `publish_state`, `updated_at`);
CREATE TABLE `compliance_evidence_requirements` ( `id` text PRIMARY KEY NOT NULL, `organisation_id` text NOT NULL, `policy_version_id` text NOT NULL, `requirement_code` text NOT NULL, `title` text NOT NULL, `description` text DEFAULT '' NOT NULL, `evidence_type` text NOT NULL CHECK ( `evidence_type` IN ( 'photo', 'document', 'declaration', 'signature', 'licence', 'invoice', 'payment', 'product', 'serial', 'decommission', 'location', 'other' ) ), `capture_timing` text NOT NULL CHECK ( `capture_timing` IN ( 'pre_install', 'during_install', 'post_install', 'any', 'periodic' ) ), `minimum_count` integer DEFAULT 1 NOT NULL CHECK (`minimum_count` >= 0), `maximum_count` integer DEFAULT 1 NOT NULL CHECK ( `maximum_count` = 0 OR `maximum_count` >= `minimum_count` ), `original_required` integer DEFAULT 0 NOT NULL CHECK ( `original_required` IN (0, 1) ), `metadata_required` integer DEFAULT 0 NOT NULL CHECK ( `metadata_required` IN (0, 1) ), `gps_required` integer DEFAULT 0 NOT NULL CHECK (`gps_required` IN (0, 1)), `date_stamp_required` integer DEFAULT 0 NOT NULL CHECK ( `date_stamp_required` IN (0, 1) ), `installer_signature_required` integer DEFAULT 0 NOT NULL CHECK ( `installer_signature_required` IN (0, 1) ), `customer_signature_required` integer DEFAULT 0 NOT NULL CHECK ( `customer_signature_required` IN (0, 1) ), `allowed_content_types` text DEFAULT '[]' NOT NULL CHECK ( json_valid(`allowed_content_types`) ), `condition_snapshot` text DEFAULT '{}' NOT NULL CHECK ( json_valid(`condition_snapshot`) ), `field_schema` text DEFAULT '{}' NOT NULL CHECK (json_valid(`field_schema`)), `source_citation` text NOT NULL, `sort_order` integer DEFAULT 0 NOT NULL CHECK (`sort_order` >= 0), `created_by_uid` text NOT NULL, `created_at` text NOT NULL, `updated_at` text NOT NULL );
CREATE UNIQUE INDEX `compliance_evidence_requirements_policy_code_idx` ON `compliance_evidence_requirements` (`policy_version_id`, `requirement_code`);
CREATE INDEX `compliance_evidence_requirements_policy_order_idx` ON `compliance_evidence_requirements` (`policy_version_id`, `sort_order`, `requirement_code`);
ALTER TABLE `compliance_cases` ADD `evidence_policy_version_id` text DEFAULT '' NOT NULL;
CREATE INDEX `compliance_cases_evidence_policy_idx` ON `compliance_cases` (`evidence_policy_version_id`, `created_at`);
CREATE TABLE `compliance_participants` ( `id` text PRIMARY KEY NOT NULL, `organisation_id` text NOT NULL, `participant_type` text NOT NULL CHECK ( `participant_type` IN ( 'installer', 'retailer', 'aggregator', 'auditor', 'supplier', 'agent' ) ), `external_reference` text DEFAULT '' NOT NULL, `legal_name` text NOT NULL, `trading_name` text DEFAULT '' NOT NULL, `abn` text DEFAULT '' NOT NULL, `contact_email` text DEFAULT '' NOT NULL, `status` text DEFAULT 'pending' NOT NULL CHECK ( `status` IN ('pending', 'active', 'suspended', 'expired', 'retired') ), `effective_from` text DEFAULT '' NOT NULL, `effective_to` text DEFAULT '' NOT NULL, `created_by_uid` text NOT NULL, `created_at` text NOT NULL, `updated_at` text NOT NULL );
CREATE INDEX `compliance_participants_org_status_idx` ON `compliance_participants` (`organisation_id`, `participant_type`, `status`, `trading_name`);
CREATE UNIQUE INDEX `compliance_participants_external_idx` ON `compliance_participants` (`organisation_id`, `external_reference`) WHERE `external_reference` <> '';
CREATE TABLE `compliance_participant_abilities` ( `id` text PRIMARY KEY NOT NULL, `organisation_id` text NOT NULL, `participant_id` text NOT NULL, `program_id` text DEFAULT '' NOT NULL, `activity_version_id` text DEFAULT '' NOT NULL, `ability_code` text NOT NULL, `ability_role` text NOT NULL, `status` text DEFAULT 'pending' NOT NULL CHECK ( `status` IN ('pending', 'active', 'suspended', 'expired', 'revoked') ), `effective_from` text NOT NULL, `effective_to` text DEFAULT '' NOT NULL, `evidence_snapshot` text DEFAULT '{}' NOT NULL CHECK ( json_valid(`evidence_snapshot`) ), `approved_by_uid` text DEFAULT '' NOT NULL, `approved_at` text DEFAULT '' NOT NULL, `created_by_uid` text NOT NULL, `created_at` text NOT NULL, `updated_at` text NOT NULL );
CREATE UNIQUE INDEX `compliance_participant_abilities_key_idx` ON `compliance_participant_abilities` (`participant_id`, `ability_code`, `effective_from`);
CREATE INDEX `compliance_participant_abilities_expiry_idx` ON `compliance_participant_abilities` (`organisation_id`, `status`, `effective_to`, `participant_id`);
CREATE TABLE `compliance_case_assignments` ( `id` text PRIMARY KEY NOT NULL, `organisation_id` text NOT NULL, `case_id` text NOT NULL, `compliance_user_id` text NOT NULL, `assignment_role` text NOT NULL CHECK ( `assignment_role` IN ( 'case_manager', 'primary_reviewer', 'secondary_reviewer', 'auditor' ) ), `status` text DEFAULT 'assigned' NOT NULL CHECK ( `status` IN ('assigned', 'released', 'completed') ), `assigned_by_uid` text NOT NULL, `assigned_at` text NOT NULL, `released_at` text DEFAULT '' NOT NULL, `completed_at` text DEFAULT '' NOT NULL );
CREATE UNIQUE INDEX `compliance_case_assignments_active_role_idx` ON `compliance_case_assignments` (`case_id`, `compliance_user_id`, `assignment_role`);
CREATE INDEX `compliance_case_assignments_user_status_idx` ON `compliance_case_assignments` (`organisation_id`, `compliance_user_id`, `status`, `assigned_at`);
CREATE TABLE `compliance_case_tasks` ( `id` text PRIMARY KEY NOT NULL, `organisation_id` text NOT NULL, `case_id` text NOT NULL, `task_type` text NOT NULL CHECK ( `task_type` IN ( 'evidence', 'review', 'correction', 'submission', 'reconciliation', 'participant', 'general' ) ), `title` text NOT NULL, `detail` text DEFAULT '' NOT NULL, `priority` text DEFAULT 'normal' NOT NULL CHECK ( `priority` IN ('low', 'normal', 'high', 'urgent') ), `status` text DEFAULT 'open' NOT NULL CHECK ( `status` IN ('open', 'in_progress', 'blocked', 'completed', 'cancelled') ), `assignee_user_id` text DEFAULT '' NOT NULL, `due_at` text DEFAULT '' NOT NULL, `created_by_uid` text NOT NULL, `completed_by_uid` text DEFAULT '' NOT NULL, `completed_at` text DEFAULT '' NOT NULL, `created_at` text NOT NULL, `updated_at` text NOT NULL );
CREATE INDEX `compliance_case_tasks_queue_idx` ON `compliance_case_tasks` (`organisation_id`, `status`, `priority`, `due_at`, `created_at`);
CREATE INDEX `compliance_case_tasks_case_idx` ON `compliance_case_tasks` (`case_id`, `status`, `created_at`);
CREATE TABLE `compliance_case_evidence` ( `id` text PRIMARY KEY NOT NULL, `organisation_id` text NOT NULL, `case_id` text NOT NULL, `requirement_id` text NOT NULL, `job_media_id` text DEFAULT '' NOT NULL, `supersedes_evidence_id` text DEFAULT '' NOT NULL, `source_type` text NOT NULL CHECK ( `source_type` IN ( 'field_app', 'installer_upload', 'customer_upload', 'import', 'registry' ) ), `status` text DEFAULT 'received' NOT NULL CHECK ( `status` IN ( 'received', 'under_review', 'accepted', 'rejected', 'superseded', 'withdrawn' ) ), `object_key` text NOT NULL, `file_name` text NOT NULL, `content_type` text NOT NULL, `size_bytes` integer NOT NULL CHECK (`size_bytes` > 0), `original_sha256` text NOT NULL CHECK ( length(`original_sha256`) = 64 AND lower(`original_sha256`) NOT GLOB '*[^0-9a-f]*' ), `evidence_envelope` text NOT NULL CHECK (json_valid(`evidence_envelope`)), `received_by_type` text NOT NULL CHECK ( `received_by_type` IN ('installer', 'compliance', 'platform') ), `received_by_uid` text NOT NULL, `received_at` text NOT NULL, `reviewed_by_uid` text DEFAULT '' NOT NULL, `reviewed_at` text DEFAULT '' NOT NULL, `retention_until` text DEFAULT '' NOT NULL, `legal_hold` integer DEFAULT 0 NOT NULL CHECK (`legal_hold` IN (0, 1)), `created_at` text NOT NULL, `updated_at` text NOT NULL );
CREATE UNIQUE INDEX `compliance_case_evidence_job_media_idx` ON `compliance_case_evidence` (`job_media_id`) WHERE `job_media_id` <> '';
CREATE INDEX `compliance_case_evidence_case_requirement_idx` ON `compliance_case_evidence` (`case_id`, `requirement_id`, `status`, `received_at`);
CREATE INDEX `compliance_case_evidence_review_idx` ON `compliance_case_evidence` (`organisation_id`, `status`, `received_at`);
